import{OCEAN_CONFIG as s}from"./config.min.js";function i(e,t,r){if(t<=e)return r>=t?1:0;const n=Math.max(0,Math.min(1,(r-e)/(t-e)));return n*n*(3-2*n)}function w(e,t,r){return e+(t-e)*r}export function arcProgress(e,t=s.storm){const r=t.seconds>0?t.seconds:1;return Math.max(0,Math.min(1,e/r))}export function stageAt(e,t=s.storm){const r=t.stages;let n=r[0];for(let a=0;a<r.length;a++)e>=r[a].from&&(n=r[a]);return n}export function stageProgress(e,t=s.storm){const r=t.stages;for(let n=0;n<r.length;n++){const a=r[n].from,o=n+1<r.length?r[n+1].from:t.seconds;if(e>=a&&(e<o||n===r.length-1))return o<=a?1:Math.max(0,Math.min(1,(e-a)/(o-a)))}return 0}export function swellAt(e,t=s.storm){return curveAt(e,t.swell,t)}export function leanAt(e,t=s.storm){return curveAt(e,t.lean,t)}export function gloomAt(e,t=s.storm){return curveAt(e,t.gloom,t)}export function surgeAt(e,t=s.storm){return curveAt(e,t.surge,t)}export function curveAt(e,t,r=s.storm){if(!t||t.length===0)return 0;if(t.length===1)return t[0].value;const n=Math.max(0,Math.min(r.seconds,e));if(n<=t[0].at)return t[0].value;const a=t[t.length-1];if(n>=a.at)return a.value;for(let o=1;o<t.length;o++)if(n<=t[o].at){const l=t[o-1],u=t[o];return w(l.value,u.value,i(l.at,u.at,n))}return a.value}export function engulfAt(e,t=s){const r=t.camera.height,n=t.storm.engulfWashMetres;return i(r,r+n,e)}export function washFloorAt(e,t=s){const r=t.camera.height,{washFloorFromMetres:n,washFloorToMetres:a}=t.storm;return i(r+n,r+a,e)}export function washEnvelope(e,t,r,n=s.storm,a=0){const o=e&&typeof e=="object"?e:{wash:0,target:0,attacking:!1},l=Math.max(0,r),u=n.washReleaseSeconds>0?n.washReleaseSeconds:1,f=n.washAttackSeconds>0?n.washAttackSeconds:.2,m=t-o.target;let c=o.attacking;l>0&&m/l>1/u&&(c=!0);let h;c?(h=Math.min(t,o.wash+l/f),h>=t-1e-9&&(c=!1)):h=Math.max(0,o.wash-l/u);const p=Math.max(0,Math.min(1,Number.isFinite(a)?a:0));return{wash:Math.max(h,p),target:t,attacking:c}}export function frontAt(e,t=s.storm){const r=t.tsunami;if(!r||e<r.startAt)return null;const n=r.arriveAt-r.startAt,a=n>0?Math.min(1,(e-r.startAt)/n):1,o=r.riseFar+(r.riseNear-r.riseFar)*a,l=Math.pow(a,.7);return{z:r.fromZ+(r.toZ-r.fromZ)*l,rise:o*i(0,.1,a),width:r.frontWidthFar+(r.frontWidthNear-r.frontWidthFar)*a,body:r.bodyMetres,foam:r.frontFoam*i(0,.15,a),swellBehind:r.swellBehind}}export function clarityAt(e,t=s.storm){return curveAt(e,t.clarity,t)}export function lullFrontAt(e,t=s.storm){const r=t.lull;if(!r||e<r.startAt)return null;const n=r.endAt-r.startAt,a=n>0?Math.min(1,(e-r.startAt)/n):1;return a>=1?null:{z:r.fromZ+(r.toZ-r.fromZ)*a,width:r.width,before:swellAt(r.startAt,t)}}export function frontLevelAt(e,t){return t?t.rise*(1-i(t.z-t.width,t.z+t.width,e)):0}export function surfaceAtCamera(e,t=s){const{beach:r,camera:n}=t,a=(n.z-r.shoreZ)*r.slope;return Math.max(a,e)}export function fadeAt(e,t=s.storm){const r=t.seconds-t.fadeSeconds;return i(r,t.seconds,e)}export function stormStateAt(e,t=s,r=null){const n=t.storm,a=surgeAt(e,n),o=frontAt(e,n),l=a+frontLevelAt(t.camera.z,o),u=r??surfaceAtCamera(l,t);return{seconds:e,progress:arcProgress(e,n),stage:stageAt(e,n).name,swell:swellAt(e,n),lean:leanAt(e,n),gloom:gloomAt(e,n),clarity:clarityAt(e,n),surge:a,front:o,lull:lullFrontAt(e,n),engulf:engulfAt(u,t),washFloor:washFloorAt(u,t),fade:fadeAt(e,n),finished:e>=n.seconds}}
